const fs=require('node:fs'),path=require('node:path');
const {createCss}=require('../docs/marketing/design-system/system.cjs');
const dir=path.resolve(__dirname,'../docs/audio/classic-bgm-20261015');
const generated=JSON.parse(fs.readFileSync(path.join(dir,'library-generation.json'),'utf8'));
const publishedPath=path.join(dir,'music-catalog.json');
const published=fs.existsSync(publishedPath)?JSON.parse(fs.readFileSync(publishedPath,'utf8')):{sets:[],legacy:[],assignments:[]};
const pigRevision=require('./build-pig-v2-listening-20261015.cjs')(dir,published.sets.find(s=>s.id==='classic-01'));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sets=generated.sets.map(s=>{const ready=published.sets.find(x=>x.id===s.id);return {...s,ready:!!ready,tracks:s.tracks.map((t,i)=>({...t,url:ready?.tracks[i]?.url,duration:ready?.tracks[i]?.duration})),bookCount:published.assignments.filter(a=>a.setIds.includes(s.id)).length};});
const payload=JSON.stringify({hasPigRevision:pigRevision.ready,sets,legacy:published.legacy,legacySets:published.sets.filter(s=>s.kind==='legacy'),assignments:published.assignments}).replace(/</g,'\\u003c');
const html=`<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>탱고북 · 이야기 음악 서재</title><style>${createCss()}
*{box-sizing:border-box}body{margin:0;background:#f8f7f2;color:#243b36;font-family:DocumentPretendard,system-ui,sans-serif}button,input,select{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer}button:disabled{cursor:default;opacity:.4}a{color:#326c60;text-underline-offset:4px}main{max-width:1180px;margin:auto;padding:52px 30px 180px}header{display:flex;justify-content:space-between;gap:28px;align-items:flex-start;border-bottom:1px solid #dce2d9;padding-bottom:32px}.eyebrow{font-size:11px;letter-spacing:.2em;color:#628076;font-weight:700}h1{font-size:clamp(32px,5vw,54px);letter-spacing:-.05em;line-height:1.2;margin:15px 0}header p{line-height:1.8;color:#6b7972;max-width:670px;margin:0;font-size:15px}.totals{display:flex;gap:26px;padding-top:28px}.totals b{font-size:30px;display:block}.totals span{font-size:11px;color:#738078;white-space:nowrap}.toplink{font-size:12px;white-space:nowrap}.filters{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:26px 0 20px}.pill{border:1px solid #d9dfd4;border-radius:22px;background:transparent;color:#66796f;padding:9px 17px;font-size:13px}.pill[aria-pressed=true]{background:#284e43;color:white;border-color:#284e43}.search{margin-left:auto;background:white;border:1px solid #d9dfd4;border-radius:10px;padding:11px 14px;min-width:220px;color:#284e43}.readyfilter{font-size:12px;color:#6e7b72;display:flex;align-items:center;gap:6px}.notice{font-size:12px;line-height:1.7;background:#eaf0e6;padding:15px 18px;border-radius:10px;color:#5a6c60;margin-bottom:25px}#count{font-size:12px;color:#6b7d70;margin-bottom:15px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.set{background:#fffefa;border:1px solid #dce1d5;border-radius:17px;padding:25px;position:relative;overflow:hidden}.set[data-genre=folktale]{--tone:#94754e;--wash:#f5eee0}.set[data-genre=classic]{--tone:#4f7464;--wash:#edf2e8}.set[data-genre=legacy]{--tone:#7c7192;--wash:#f0edf5}.badge{display:inline-flex;border-radius:6px;padding:4px 8px;font-size:10px;font-weight:600;color:var(--tone);background:var(--wash);letter-spacing:.03em}.sethead{display:flex;justify-content:space-between;gap:15px;align-items:center}h2{font-size:23px;letter-spacing:-.035em;margin:14px 0 8px}.instruments{font-size:12px;line-height:1.8;color:#758075;min-height:42px;margin:0 0 18px}.setplay{background:var(--tone);border:0;color:white;border-radius:30px;padding:10px 16px;font-size:12px;white-space:nowrap}.track{display:flex;gap:12px;align-items:center;border-top:1px solid #ecefe5;padding:12px 0}.trackplay{border:1px solid #dce2d6;color:var(--tone);background:white;border-radius:50%;width:34px;height:34px;flex-shrink:0;font-size:12px}.trackinfo{flex:1;min-width:0}.role{font-size:13px;font-weight:600}.duration{font-size:11px;color:#8a9388;margin-left:7px;font-variant-numeric:tabular-nums}.track small{display:block;font-size:10px;color:#959c91;margin-top:4px}.compare{display:flex;gap:8px;font-size:10px}.compare a{text-decoration:none;color:#8c958b;white-space:nowrap}.compare a:hover{text-decoration:underline}.setfoot{display:flex;justify-content:space-between;border-top:1px solid #ecefe5;padding-top:14px;font-size:10px;color:#8a9488;gap:12px}.empty{padding:50px;text-align:center;color:#7e8c80}.player{position:fixed;bottom:0;left:0;right:0;background:rgba(250,250,245,.97);border-top:1px solid #d4ddce;backdrop-filter:blur(16px);z-index:10;padding:15px 30px}.playerinner{max-width:1120px;margin:auto;display:flex;align-items:center;gap:18px}.now{min-width:225px;max-width:320px}.now small{display:block;font-size:10px;letter-spacing:.12em;color:#7c8f7d;margin-bottom:5px}.now strong{font-size:13px;line-height:1.6}.transport{display:flex;gap:6px}.transport button{border:1px solid #d5dfd0;background:#fff;border-radius:50%;width:36px;height:36px;color:#355a48}.player audio{flex:1;min-width:160px;height:38px}.footerhint{font-size:10px;text-align:center;color:#98a08f;margin:9px 0 0}.set .booklist{font-size:11px;line-height:1.8;color:#758075;margin:12px 0 0}.booklist summary{cursor:pointer}.booklist a{display:inline-block;margin-right:10px}.subhead{grid-column:1/-1;font-size:14px;font-weight:600;margin:10px 0 0;color:#687b6e}.focus{outline:2px solid #90ac88;outline-offset:2px}button:focus-visible,a:focus-visible{outline:3px solid #cfb477;outline-offset:3px}[hidden]{display:none!important}@media(max-width:740px){main{padding:22px 18px 210px}header{display:block}header p{font-size:12px;line-height:1.65}h1{margin:12px 0}.notice{padding:12px 14px}.totals{padding-top:20px}.grid{grid-template-columns:1fr}.search{width:100%;margin-left:0;min-width:0}.set{padding:20px}.player{padding:12px 15px}.playerinner{flex-wrap:wrap;gap:10px}.now{flex:1;min-width:0;max-width:none}.player audio{width:100%;flex-basis:100%}.instruments{min-height:0}.compare{gap:6px}}${pigRevision.css}</style></head><body><main><header><div><div class="eyebrow">TANGOBOOK / SOUND LIBRARY</div><h1>이야기에 어울리는,<br>세 곡의 흐름.</h1><p>도입에서 클라이맥스, 마지막 여운까지. 명작과 전래의 음악을 나누어 듣고, 한 세트가 어떻게 이어지는지 비교해 보세요.</p><div class="totals"><div><b>20</b><span>새 음악 세트</span></div><div><b>${generated.sets.flatMap(s=>s.tracks).reduce((n,t)=>n+t.candidates.length,0)+(pigRevision.ready?6:0)}</b><span>Suno 생성 후보</span></div><div><b>${sets.filter(s=>s.ready).length}</b><span>바로 듣는 새 세트</span></div><div><b>${published.legacy.length}</b><span>기존 음악</span></div></div></div><a class="toplink" href="index.html#library">제작 기획서 ↗</a></header>${pigRevision.html}<div class="filters" aria-label="음악 필터"><button class="pill" data-filter="all" aria-pressed="true">전체</button><button class="pill" data-filter="classic" aria-pressed="false">명작동화</button><button class="pill" data-filter="folktale" aria-pressed="false">전래동화</button><button class="pill" data-filter="legacy" aria-pressed="false">기존 음악</button><input class="search" id="search" aria-label="음악 검색" placeholder="세트 이름이나 분위기 검색"><label class="readyfilter"><input id="ready" type="checkbox" checked>바로 재생 가능</label></div><div class="notice">‘세트 듣기’는 도입 → 클라이맥스 → 마지막을 차례로 재생합니다. 파일이 없는 후보는 Suno에서 들어보세요.</div><div id="count" aria-live="polite"></div><div id="cards" class="grid"></div><details class="notice" style="margin-top:24px"><summary>음원 선별·파일 안내</summary><p>파일 확보본은 음량·무음·발화 의심 구간을 자동 검사한 1차 편성입니다. 음악적 완성도와 보컬 혼입에 대한 사람 청취 검수는 별도입니다. 기존 13개 제목 중 두 쌍은 같은 오디오여서 11개 원음으로 보존했습니다. 나머지 새 세트는 Suno 후보 링크로 비교할 수 있습니다.</p></details></main><section class="player" aria-label="음악 플레이어"><div class="playerinner"><div class="now" aria-live="polite"><small>NOW LISTENING</small><strong id="now">들어볼 곡이나 세트를 선택해 주세요.</strong></div><div class="transport"><button id="prev" aria-label="이전 곡" disabled>‹</button><button id="toggle" aria-label="음악 재생" disabled>▶</button><button id="next" aria-label="다음 곡" disabled>›</button></div><audio id="audio" controls preload="metadata" aria-label="선택한 배경음악"></audio></div><p class="footerhint" id="status">미리듣기 음량은 책 읽기 음량과 별도로 조절할 수 있습니다.</p></section><script id="music-data" type="application/json">${payload}</script><script>
const data=JSON.parse(document.getElementById('music-data').textContent),audio=document.getElementById('audio');let filter='all',queue=[],at=0,playVersion=0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=s=>s?Math.floor(s/60)+':'+String(Math.round(s%60)).padStart(2,'0'):'';
const mood={ 'classic-01':'피치카토 · 바순 · 클라리넷','classic-02':'하프 · 셀레스타 · 플루트','classic-03':'작은 현악 · 오보에 · 하프','classic-04':'첼로 · 클라리넷 · 마림바','classic-05':'펠트 피아노 · 첼로 · 별빛','classic-06':'하프 · 플루트 · 바다','classic-07':'바순 · 클라리넷 · 호기심','classic-08':'펠트 피아노 · 첼로 · 다정한 이별','classic-09':'피치카토 · 목금 · 장난','classic-10':'현악 · 피아노 · 용기','folktale-01':'가야금 · 대금 · 해금 · 햇살','folktale-02':'거문고 · 대금 · 산골','folktale-03':'가야금 · 단소 · 장난','folktale-04':'가야금 · 대금 · 달빛','folktale-05':'거문고 · 가야금 · 용기','folktale-06':'가야금 · 단소 · 신비','folktale-07':'가야금 · 거문고 · 도깨비','folktale-08':'가야금 · 대금 · 강물','folktale-09':'가야금 · 해금 · 가족','folktale-10':'거문고 · 대금 · 고요한 여운'};
function render(){const q=document.getElementById('search').value.trim().toLowerCase(),ready=document.getElementById('ready').checked;const cards=[];const rev=document.getElementById('pig-revision');if(rev){const f=document.getElementById('pig-frame');rev.hidden=filter==='folktale'||filter==='legacy'||!!(q&&!('아기 돼지 아기돼지 새 버전 경쾌 긴장 편안'.includes(q)));if(rev.hidden){f.src='about:blank';f.hidden=true;document.getElementById('pig-embed-hint').hidden=false;}else if(f.hidden&&audio.paused&&typeof showPig==='function'){showPig(pigRole,pigCandidate);}}for(const s of data.sets){if(s.id==='classic-01'&&data.hasPigRevision)continue;if(filter!=='all'&&filter!==s.genre)continue;if(ready&&!s.ready)continue;if(q&&!(s.name+' '+s.instruments+' '+mood[s.id]).toLowerCase().includes(q))continue;cards.push('<article class="set" data-genre="'+s.genre+'"><div class="sethead"><span class="badge">'+(s.genre==='classic'?'명작':'전래')+' '+s.id.split('-')[1]+' · '+(s.ready?'파일 확보':'Suno 후보')+'</span><button class="setplay" data-set="'+s.id+'" '+(!s.ready?'disabled':'')+'>▶ 세트 듣기</button></div><h2>'+esc(s.name)+'</h2><p class="instruments">'+esc(mood[s.id]||s.instruments)+'</p>'+s.tracks.map((t,i)=>'<div class="track"><button class="trackplay" data-track="'+s.id+':'+i+'" aria-label="'+esc(s.name+' '+['도입','클라이맥스','마지막'][i]+' 재생')+'" '+(!t.url?'disabled':'')+'>▶</button><div class="trackinfo"><span class="role">'+['도입','클라이맥스','마지막'][i]+'</span><span class="duration">'+time(t.duration)+'</span><small>'+(t.url?'페이지에서 바로 듣기':'Suno에서 후보 비교')+'</small></div><div class="compare">'+t.candidates.map((c,j)=>'<a target="_blank" rel="noopener" href="'+esc(c.url)+'">후보 '+(j+1)+' ↗</a>').join('')+'</div></div>').join('')+'<div class="setfoot"><span>세 곡을 한 묶음으로 유지</span><span>'+s.bookCount+'권 후보에 연결</span></div></article>');}
if(filter==='all'||filter==='legacy'||filter==='classic'){for(const s of data.legacySets){if(q&&!s.name.includes(q))continue;cards.push('<article class="set" data-genre="legacy"><div class="sethead"><span class="badge">기존 음악 편성</span><button class="setplay" data-set="'+s.id+'">▶ 세트 듣기</button></div><h2>'+esc(s.name)+'</h2><p class="instruments">기존 음원을 도입·클라이맥스·마지막의 흐름으로 다시 묶었습니다.</p>'+s.tracks.map((t,i)=>'<div class="track"><button class="trackplay" data-track="'+s.id+':'+i+'" aria-label="'+esc(t.title+' 재생')+'">▶</button><div class="trackinfo"><span class="role">'+['도입','클라이맥스','마지막'][i]+' · '+esc(t.title)+'</span><span class="duration">'+time(t.duration)+'</span></div></div>').join('')+'<div class="setfoot">원본 음원과 기존 책 지정은 보존합니다.</div></article>');}}
if(filter==='legacy')for(const t of data.legacy){if(q&&!t.title.toLowerCase().includes(q))continue;cards.push('<article class="set" data-genre="legacy"><span class="badge">기존 원곡</span><h2>'+esc(t.title)+'</h2><p class="instruments">'+time(t.duration)+' · 원곡을 정규화한 미리듣기</p><button class="setplay" data-set="single-'+t.id+'">▶ 원곡 듣기</button></article>');}
document.getElementById('count').textContent=cards.length+'개 항목 · 명작과 전래는 서로 섞이지 않습니다.';document.getElementById('cards').innerHTML=cards.join('')||'<p class="empty">이 조건에 맞는 세트가 없습니다.</p>';}
function allSets(){return [...data.sets,...data.legacySets,...data.legacy.map(t=>({id:'single-'+t.id,name:t.title,kind:'single',tracks:[t]}))]}
async function start(){const version=++playVersion;const pf=document.getElementById('pig-frame');if(pf){pf.src='about:blank';pf.hidden=true;document.getElementById('pig-embed-hint').hidden=false;}const t=queue[at];if(!t?.url)return;audio.src=t.url;document.getElementById('toggle').disabled=false;document.getElementById('now').textContent=t.display;document.getElementById('prev').disabled=at<=0;document.getElementById('next').disabled=at>=queue.length-1;document.getElementById('status').textContent=queue.length>1?'세트 연속듣기 · '+(at+1)+' / '+queue.length:'한 곡 미리듣기';try{await audio.play()}catch(err){if(version!==playVersion||err.name==='AbortError')return;document.getElementById('status').textContent='플레이어 재생 버튼을 눌러 주세요. 음원 연결에 문제가 있으면 후보 링크로 들어보세요.'}}
document.getElementById('cards').addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.set){const s=allSets().find(x=>x.id===b.dataset.set);queue=s.tracks.map((t,i)=>({...t,display:s.name+' · '+(s.kind==='single'?'원곡':['도입','클라이맥스','마지막'][i])}));at=0;start()}if(b.dataset.track){const [id,i]=b.dataset.track.split(':'),s=allSets().find(x=>x.id===id);queue=[{...s.tracks[+i],display:s.name+' · '+['도입','클라이맥스','마지막'][+i]}];at=0;start()}});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render()}));document.getElementById('search').addEventListener('input',render);document.getElementById('ready').addEventListener('change',render);document.getElementById('next').addEventListener('click',()=>{if(at<queue.length-1){at++;start()}});document.getElementById('prev').addEventListener('click',()=>{if(at>0){at--;start()}});audio.addEventListener('ended',()=>{if(at<queue.length-1){at++;start()}});audio.addEventListener('error',()=>{document.getElementById('status').textContent='음원을 불러오지 못했습니다. 잠시 후 다시 재생하거나 Suno 후보 링크로 들어보세요.'});document.getElementById('toggle').addEventListener('click',()=>{if(audio.paused){audio.play().catch(()=>{document.getElementById('status').textContent='재생을 시작하지 못했습니다.'})}else audio.pause()});audio.addEventListener('play',()=>{document.getElementById('toggle').textContent='Ⅱ';document.getElementById('toggle').setAttribute('aria-label','음악 일시정지')});audio.addEventListener('pause',()=>{document.getElementById('toggle').textContent='▶';document.getElementById('toggle').setAttribute('aria-label','음악 재생')});audio.volume=.8;render();
${pigRevision.js}
</script></body></html>`;
fs.writeFileSync(path.join(dir,'listen.html'),html);console.log('Saved listening page',sets.filter(s=>s.ready).length,'new playable suites');
